                while (i < __end_11) : (i += 1) {
                    const r = lockfile.buffers.resolutions.items[@as(usize, @intCast(i))];
                    if ((r == unset_package_id)) {
                        _ = debug("resolution index '{d}' was not set", .{ i });
                        crash = true;
                    }
                }
            }
            if (crash) {
                _ = std.debug.panic("Assertion failure, see above", .{});
            }
        }
        var is_missing_resolutions = false;
        _ = &is_missing_resolutions;
        {
            var i: i32 = 0;
            _ = &i;
            const __end_12 = resolutions.len;
            while (i < __end_12) : (i += 1) {
