                if ((r.tag == .uninitialized)) {
                    _ = Output.warn("Could not resolve package '{s}' in lockfile during migration", .{ lockfile.packages.items(.name)[@as(usize, @intCast(i))].slice(lockfile.buffers.string_bytes.items) });
                    is_missing_resolutions = true;
                } else {
                    if (Environment.allow_assert) {
                        _ = bun.assert((lockfile.getPackageID(lockfile.packages.items(.name_hash)[@as(usize, @intCast(i))], null, (&r)) != null));
                    }
                }
            }
        }
        if (is_missing_resolutions) {
            return error.NotAllPackagesGotResolved;
        }
        _ = try lockfile.resolve(log);
        if (Environment.allow_assert) {
            _ = try lockfile.verifyData();
        }
        lockfile.meta_hash = try lockfile.generateMetaHash(false, lockfile.packages.len);
        return LoadResult{ .ok = .{ .lockfile = lockfile, .migrated = .npm, .loaded_from_binary_lockfile = false } };
}

pub fn packageNameFromPath(pkg_path: []const u8) []const u8 {
        if ((pkg_path.len == 0)) {
            return "";
        }
        var pkg_name_start: usize = 0;
        _ = &pkg_name_start;
        if (strings.lastIndexOf(pkg_path, "/node_modules/")) |last_index| {
            _ = &last_index;
            pkg_name_start = (last_index + "/node_modules/".len);
        } else {
            if (strings.hasPrefixComptime(pkg_path, "node_modules/")) {
                pkg_name_start = "node_modules/".len;
            } else {
                if (strings.lastIndexOf(pkg_path, "/")) |idx| {
                    _ = &idx;
                    pkg_name_start = idx;
                } else {
                    pkg_name_start = 0;
                }
            }
        }
        return pkg_path[pkg_name_start..];
}
